import csv
from pathlib import Path

def csv_batches(path: str | Path, batch_size: int):
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        batch: list[dict] = []
        for row in reader:
            batch.append(row)
            if len(batch) >= batch_size:
                yield batch
                batch = []
        if batch:
            yield batch

